\varlimsup_{\varepsilon \to 0+}\varepsilon \log Q^\varepsilon[Y \smallsetminus F] \le -M.
\end{align*}
Suppose $P^\varepsilon = Q^\varepsilon \circ g^{-1}$ for some continuous bijection $g \colon Y \to X$. 
Then, the family $(Q^\varepsilon)_{\varepsilon > 0}$ satisfies an LDP with good rate function $J = I \circ g \colon Y \to [0,+\infty]$.\end{enumerate}

