{\bf Chordal case.}
In our notation, for integers $N > n$, the result in \cite[Equation~(A.10)]{Peltola-Wang:LDP} implies that there exists $\kappa_0 < 4$ such that
\begin{align*}
\cHmeas{\kappa}[\creturnevent{n}{N}] \le a(\kappa) \, \Big( \frac{n}{N} \Big)^{8/\kappa-1} 
\qquad \textnormal{and} \qquad a := \sup_{\kappa \in (0,\kappa_0)}\kappa\log a(\kappa) \in (-\infty, \infty) .
\end{align*}
Since for $\kappa < 4$ we have $\frac{8}{\kappa}-1 \ge \frac{4}{\kappa}$, we see that for $N > n$ we have $\smash{(\frac{n}{N})^{8/\kappa-1} \le (\frac{n}{N})^{4/\kappa}}$.
We~may thus bound the probability in~\eqref{eq:return-estimates}
\begin{align*}
\cHmeas{\kappa}[\creturnevent{n}{N}] 
\; \le \; e^{a/\kappa} \, \Big( \frac{n}{N} \Big)^{4/\kappa} 
\; = \; \exp \Big(\tfrac{a \, + \, 4\, (\log n - \log N)}{\kappa} \Big), \qquad \kappa < \kappa_0 .
\end{align*}
Choosing $N > n$ large enough gives the result with $c = 1$.


{\bf Radial case.}
\cite[Theorem~1]{Lawler:Continuity_of_radial_and_two-sided_radial_SLE_at_the_terminal_point}, 
with correction in~\cite[Theorem~1.2]{Field-Lawler:Escape_probability_and_transience_for_SLE}, 
implies that there exists a $\kappa$-dependent constant $c(\kappa) \in (0,\infty)$ such that
for all integers $N > n$, 
\begin{align*}
\rDmeas{\kappa}[\returnevent{n}{N}] \le c(\kappa) \, \exp\Big( \! -(\tfrac{N-n}{2})(\tfrac{8}{\kappa} - 1)\Big) 
, \qquad \kappa \in (0,4] .
\end{align*}
To prove the asserted bound~\eqref{eq:return-estimates}, we must track the $\kappa$-dependence in the constant $c(\kappa)$.


As in the proof of~\cite[Theorem~1]{Lawler:Continuity_of_radial_and_two-sided_radial_SLE_at_the_terminal_point} 
(and in~\cite[Proposition~3.2]{Field-Lawler:Escape_probability_and_transience_for_SLE}), 
recalling the notation~\eqref{eqn:return-event-time},  
note that $\partial \mathbb{D}_n \cap (\mathbb{D} \smallsetminus \gamma^{\kappa}[0,\rhittingtime[N]])$ is a union of crosscuts of the form 
$\eta_j = \{ e^{-n+\mathrm{i} \theta} \;|\; \theta \in ( \vartheta_j^{\min}, \vartheta_j^{\max} ) \}$. In particular, the event $\returnevent{n}{N}$ is equivalent with the existence of $\eta_j$ such that $\gamma[\rhittingtime[N], \infty) \cap \eta_j \ne \emptyset$. 
Note also that the random time increments $\rhittingtime[{m+1}] - \rhittingtime[m]$, for $m \in \mathbb{N}$, 
are uniformly bounded from above by some constant $t > 0$. 
If we denote for each $m \in \mathbb{N}$ by $\eta_j(m) := g^\kappa_{\rhittingtime[N+m]}(\eta_j)$ the image of the crosscut $\eta_j$ under the mapping-out function $g^\kappa_{\rhittingtime[N+m]} \colon \mathbb{D}\smallsetminus \gamma^\kappa[0,\rhittingtime[N+m]] \to \mathbb{D}$, we may thus estimate
\begin{align}\label{eqn:return-estimate-0}
\begin{split}
\rDmeas{\kappa}[\returnevent{n}{N}] \le\;& \sum_{m = 0}^\infty \rDmeas{\kappa} \Big[ \gamma^\kappa[\rhittingtime[N+m], \rhittingtime[N+m]+t] \cap \bigcup_j \eta_j \ne \emptyset \;\Big|\; \gamma^\kappa[\rhittingtime[N], \rhittingtime[N+m]] \cap \partial \mathbb{D}_n = \emptyset \Big]\\
=\;& \sum_{m=0}^\infty \rDmeas{\kappa}\Big[\gamma^\kappa[0,t] \cap \bigcup_j \eta_j(m) \ne \emptyset\Big],
\end{split}
\end{align}
where the last equality follows from domain Markov property. 
\cite[Lemma~4.2]{Lawler:Continuity_of_radial_and_two-sided_radial_SLE_at_the_terminal_point} shows the existence of a constant $c_t(\kappa)$ depending on $\kappa$ (and $t$) such that any $\mathbb{D}$-crosscut $\eta$ satisfies
\begin{align}\label{eqn:return-probability-finite}
\rDmeas{\kappa}\Big[\gamma^\kappa[0,t] \cap \eta \ne \emptyset\Big] \le c_t(\kappa)\bigg( \frac{\mathrm{diam}\,(\eta)}{\mathrm{dist}\,(1,\eta)} \bigg)^{8/\kappa-1}
\end{align}
Let $N-n \ge N_0$ so that \Cref{thm:crosscut-estimate} is applicable. 
We may bound the summands in~\eqref{eqn:return-estimate-0} by taking the supremum over all possible collections of $\eta_j$'s 
(writing $\Delta\theta_j := \theta_j^{\max}-\theta_j^{\min}$):
\begin{align*}
&\rDmeas{\kappa}\Big[\gamma^\kappa[0,t] \cap \bigcup_j \eta_j(m) \ne \emptyset\Big] \\
&\le \sup_{\{\eta_j\}_j} \sum_j \rDmeas{\kappa}\big[\gamma^\kappa[0,t] \cap \eta_j(m) \ne \emptyset\big] && \textnormal{[by the union bound]} \\
&\le c_t(\kappa) \sup_{\{\eta_j\}_j} \sum_j\Big(C \, e^{-(N+m-n)/2}\Delta\theta_j\Big)^{8/\kappa - 1}  && \textnormal{[by~\eqref{eqn:return-probability-finite}~\&~\Cref{thm:crosscut-estimate}]} \\
&\le c_t(\kappa) \, (2\pi C)^{\frac{8}{\kappa}-1} \, (e^{-\frac{8-\kappa}{2\kappa}})^{m}e^{-(\frac{N-n}{2})(\frac{8}{\kappa}-1)} . && 
\textnormal{\Big[use $\sum_j \Delta\theta_j = 2\pi$ and $L^p$-norm monotonicity\Big]}
\end{align*}
The right-hand side of~\eqref{eqn:return-estimate-0} can be bounded\footnote{With ``$\lesssim$'', we indicate an upper bound up to a universal constant independent of $\kappa$.} 
by summing the above estimate over $m \in \mathbb{N}$:
\begin{align}\label{eqn:return-estimate-1}
\rDmeas{\kappa}[\returnevent{n}{N}] 
\;\le\; \frac{c_t(\kappa) \,  (2\pi C)^{\frac{8}{\kappa}-1}}{1-e^{-\frac{8-\kappa}{2\kappa}}} \, e^{-(\frac{N-n}{2})(\frac{8}{\kappa}-1)} 
\;\lesssim\; c_t(\kappa) \, \exp\Big( \tfrac{\xi \, - \, 4 \, (N-n)}{\kappa}\Big) 
, \qquad \kappa \le 4 ,
\end{align}
where $\xi \in \mathbb{R}$ is a universal constant.  
It remains to bound $c_t(\kappa)$ in~\eqref{eqn:return-probability-finite} (with $\eta = \eta_j(m)$ for some $j, m$). 
We fix $\ell \in \mathbb{N}$ such that $\rho := \rhittingtime[\ell] > t$  and consider the stopping time 
\begin{align*}
\sigma := \sigma(\gamma^{\kappa})
:= \; & \inf\{t \ge 0 \colon \operatorname{Re} (\gamma^{\kappa}(t)) = e^{-2\ell} \} ,
\qquad \textnormal{writing} \qquad 
p^{\kappa} := \rDmeas{\kappa}[\rho < \sigma]
\end{align*}
(see also~\Cref{fig:return-estimate-constructions}). 
Using the Radon-Nikodym derivative~\eqref{eqn:radial-chordal-RN-derivative}, 
we also define
\begin{align}\label{eq:Radon-Nikodym_estimate}
\begin{split}
R^{\kappa}
:=\;& \sup_{\gamma \in \Dpaths[\rho\wedge\sigma]} 
\frac{\,\mathrm{d} \rDmeasure[\rho\wedge\sigma]{\kappa}}{\,\mathrm{d} \cDmeasure[\rho\wedge\sigma]{\kappa}}(\gamma) 
\\
= \;& \sup_{\Theta} \;
\exp\bigg(\frac{6-\kappa}{4\kappa}\bigg((\kappa-4) (\rho\wedge\sigma) 
+ \int_0^{\rho\wedge\sigma} \frac{\,\mathrm{d} s}{\sin^2(\Theta_s)}\bigg)\bigg) 
\big|\sin (\Theta_{\rho\wedge\sigma})\big|^{6/\kappa - 1} ,
\end{split}
\end{align} 
where $\Theta$ is associated to $\gamma$ via 
$e^{2\mathrm{i}\Theta_s} = \frac{g_s(-1)}{g_s(\gamma(s))}$, 
the radial Loewner map $g_s \colon \mathbb{D} \smallsetminus \gamma[0,s] \to \mathbb{D}$.
From the unnumbered equation before~\cite[Equation~(36), proof of Lemma~4.2]{Lawler:Continuity_of_radial_and_two-sided_radial_SLE_at_the_terminal_point},
\begin{align}\label{eqn:crosscut-probability}
\rDmeas{\kappa}\big[\gamma^\kappa[0,t] \cap \eta \ne \emptyset\big] 
\le \frac{R^\kappa}{1-p^\kappa} \, \cDmeas{\kappa}\big[\gamma^\kappa[0,\sigma \wedge \rho] \cap \eta \ne \emptyset\big], \qquad \kappa \in (0,8).
\end{align} 
For our purposes, it suffices to 
restrict to the range $\kappa \in (0,4]$, where $\SLE[\kappa]$ curves are almost surely simple. 
To estimate the quantity $R^{\kappa}$ in~\eqref{eq:Radon-Nikodym_estimate}, we write $D_s = \mathbb{D} \smallsetminus \gamma[0,s]$, 
and we partition its boundary as $\partial D_s = \partial_+\cup \partial_-\cup\partial_s^+\cup\partial_s^-$, 
where $\partial_\pm = \arc{\pm 1}{\mp 1}$ are the counterclockwise arcs between $\pm 1$ and $\mp 1$,
and $\partial_s^+$ and $\partial_s^-$ are the right and left boundaries of $\gamma(0,s)$, respectively 
(see \Cref{fig:return-estimate-constructions} for an illustration). 
Then, we have
\begin{align*}
\Theta_s = \tfrac{1}{2}\big(\arg(g_t(-1))-\arg(g_t(\gamma(t)))\big) 
= \pi \, \harmonicmeasure{\mathbb{D}}{0}{\arc{g_t(\gamma(t))}{g_t(-1)}} 
= \pi \, \harmonicmeasure{D_s}{0}{\partial_+\cup\partial_s^+},
\end{align*}
where $\harmonicmeasure{D}{z}{\cdot}$ denotes the harmonic measure in $D$ seen from $z \in D$,
and the last equality holds by conformal invariance of the harmonic measure. 
When $s \le \rho \wedge \sigma$, we have 
$D' := \component{\mathbb{D}\smallsetminus(e^{-2\ell}+\mathrm{i}\mathbb{R})}{0} \subset D_s$. 
Since $\arc{\mathrm{i}}{-1} \subset \partial D' \cap \partial_+$, we obtain the uniform bound
\begin{align*}
\Theta_s \ge  \pi \, \harmonicmeasure{D'}{0}{\arc{\mathrm{i}}{-1}} =: \delta > 0 .
\end{align*}
We similarly obtain $\pi - \Theta_s \ge \delta > 0$. 
Since $\rho \le \ell$, with~\eqref{eq:Radon-Nikodym_estimate} it thus follows that 
\begin{align}\label{eq:Radon-Nikodym_estimate_exp}
R^{\kappa} \lesssim \;& e^{c/\kappa} , \qquad \kappa \in (0,4] ,
\end{align} 
where $c \in (0,\infty)$ is a universal constant. 


To estimate the probability $p^{\kappa}:= \rDmeas{\kappa}[\rho < \sigma]$, we use \Cref{thm:open-sets-have-finite-energy}. 
First, note that as $\rho \le \ell$, the event $\{\sigma \le \rho\}$ is measurable for $\rDmeasure[\ell]{\kappa}$.
Let $A := \{z \in \partial\mathbb{D}_\ell \;|\; \operatorname{Re}(z) \ge e^{-2\ell}\}$ 
and $U := \{F \in \mathcal{C} \;|\; F \cap A = \emptyset\}$.
Because each curve $\gamma \in U \cap \Dpaths$ satisfies $\sigma(\gamma) \le \rho \le \ell$, we obtain
\begin{align*}
\varliminf_{\kappa \to 0+} \kappa \log (1 - p^{\kappa})
\; = \; \varliminf_{\kappa \to 0+} \kappa \log \rDmeasure[\ell]{\kappa}[\sigma \leq \rho] 
\; \ge \; \varliminf_{\kappa \to 0+} \kappa \log \rDmeasure[\ell]{\kappa}[U] 
\; \ge \; - \renergy[\ell](U) > -\infty,
\end{align*}
using the finite-time LDP for the Hausdorff metric (\Cref{thm:LDP-compact})
and noting that, since $U \subset \mathcal{C}$ is an Hausdorff-open subset and $\Dpaths[\ell] \cap U \ne \emptyset$,
\Cref{thm:open-sets-have-finite-energy} implies that $\renergy[\ell](U) < \infty$. 
Hence, there exists $\kappa_0 \leq 4$ such that 
\begin{align}\label{eqn:p-kappa_estimate}
\frac{1}{1-p^\kappa} \le \exp \Big(\tfrac{\renergy[\ell](U) \, + \, 1}{\kappa} \Big) < \infty, \qquad \kappa \in (0,\kappa_0].
\end{align}

With the quantities $R^{\kappa}$ and $p^\kappa$ estimated, 
it remains to bound the probability on the right-hand side of~\eqref{eqn:crosscut-probability}, that is, 
$\cDmeas{\kappa}[\gamma^\kappa[0,\sigma \wedge \rho] \cap \eta \ne \emptyset]$. 
If $\eta \subset D'$, then this probability is zero, so we assume that $\eta \not\subset D'$. 
By \Cref{thm:crosscut-estimate}, by taking $N$ sufficiently large 
we may without loss of generality assume that $\mathrm{diam}\,(\eta) < 1/2$, 
so that $\eta \subset \component{\mathbb{D}\smallsetminus\{-1/2 + \mathrm{i}\mathbb{R}\}}{0} =: D''$. 
Since the map $(\Phi_{\mathbb{H}}^{-1})'$ is uniformly bounded away from $0$ and $\infty$ on $D''$,
we see that 
\begin{align*}
\frac{\mathrm{diam}\,(\Phi_{\mathbb{H}}^{-1}(\eta))}{\mathrm{dist}\,(0, \Phi_{\mathbb{H}}^{-1}(\eta))} \le \hat c \, \bigg(\frac{\mathrm{diam}\,(\eta)}{\mathrm{dist}\,(1, \eta)}\bigg) ,
\end{align*}
where $\hat c \in [0,\infty)$ is a universal constant.
We thus obtain the bound
\begin{align*}
\cDmeas{\kappa}\big[\gamma^\kappa[0,\sigma \wedge \rho] \cap \eta \ne \emptyset\big] 
\; \le \;\; & \cHmeas{\kappa}\big[\gamma^\kappa \cap \Phi_{\mathbb{H}}^{-1}(\eta) \ne \emptyset\big] 
&& \textnormal{[by conf.~inv.]} \\
\; \lesssim \;\; & \hat c^{8/\kappa} \, e^{\zeta/\kappa} \, \bigg(\frac{\mathrm{diam}\,(\eta)}{\mathrm{dist}\,(1, \eta)}\bigg)^{8/\kappa - 1}
, \qquad \kappa \in (0,4] .
&& \textnormal{[by \Cref{thm:crosscut-half-plane}]}
\end{align*}
Combining this with the estimates in~\eqref{eq:Radon-Nikodym_estimate_exp}~\&~\eqref{eqn:p-kappa_estimate} to~\eqref{eqn:crosscut-probability} yields  
\begin{align*}
\rDmeas{\kappa}\big[\gamma^\kappa[0,t] \cap \eta \ne \emptyset\big] 
\lesssim e^{\hat{\xi} / \kappa} \bigg(\frac{\mathrm{diam}\,(\eta)}{\mathrm{dist}\,(1, \eta)}\bigg)^{8/\kappa - 1}, \qquad \kappa \le \kappa_0 ,
\end{align*}
for some universal constant $\hat \xi \in \mathbb{R}$. 
Comparing this with~\eqref{eqn:return-probability-finite}, 
we see that we may choose 
$c_t(\kappa) \gtrsim e^{\hat{\xi}/\kappa}$ in the range $\kappa \in (0,\kappa_0]$. 
Plugging this back to~\eqref{eqn:return-estimate-1} finally gives 
\begin{align*}
\rDmeas{\kappa}[\returnevent{n}{N}] \lesssim 
\exp\Big( \tfrac{\hat \xi \, + \, \xi- \, 4 \, (N-n)}{\kappa}\Big) 
, \qquad \kappa \in (0, \kappa_0].
\end{align*}
Hence, after choosing $N$ large enough we obtain the desired result.

