\begin{align*}
- \lenergy{\mathbf{D}}{\mathfrak{z},\mathfrak{w}}(\xreturnevent{n}{N_{n+1}+1}) 
\leq \;&
\varliminf_{\kappa \to 0+}\kappa\log\SLEmeasure{\mathbf{D};\mathfrak{z},\mathfrak{w}}{\kappa}[\xreturnevent{n}{N_{n+1}+1}]
&& \textnormal{[by~\eqref{eq:LDP_bounds} in \Cref{thm:radial-LDP-bounds}]}
\\
\leq \;&
\varlimsup_{\kappa \to 0+}\kappa\log\SLEmeasure{\mathbf{D};\mathfrak{z},\mathfrak{w}}{\kappa}[\xreturnevent{n+1}{N_{n+1}}]
\; \leq \; - M ,
&& \textnormal{[by \Cref{thm:return-estimates}]}
\end{align*}

\label{thm:goodness-energy}
The Loewner energy $\lenergy{D}{x,y} \colon \Xpaths(D;x,y) \to [0,+\infty]$
defined in~\eqref{eqn:radial-energy-definition} is a good rate function 
\textnormal{(}with respect to the topology induced by $\dXpaths$\textnormal{)}
in the sense of \Cref{def:LDP}.

\begin{align*}
\smash{\cev \Xlenergy}(\smash{\cev{\Xpaths}} \smallsetminus \cev F_{\vec N}) = 
\Xlenergy[](\Xpaths[\infty] \smallsetminus F_{\vec N}) \geq M ,
\qquad \textnormal{where}
\qquad 
\begin{cases}
\cev F_{\vec N} := \smash{\cev\iota} (F_{\vec N}) , \\ 
F_{\vec N} := \smash{\underset{n \in \mathbb{N}}{\bigcap}} (\Xpaths[\infty] \smallsetminus \xreturnevent{n}{N_n}) ,
