\end{align*}

Examining the proof of~\cite[Theorem~1.5]{Peltola-Wang:LDP}, we see that the proof of~\cite[Theorem~5.11]{Peltola-Wang:LDP} also proves \Cref{thm:multichordal-LDP} verbatim once we establish the following facts: 
\begin{enumerate}[leftmargin=*, label=\textnormal{(\roman*)}]
\item \label{item_multi1}
\Cref{thm:multichordal-LDP} in the case of $n=1$; 

\item \label{item_multi2}
continuity of the Brownian loop measure term $\loopterm{D} \colon \Hpaths[\alpha] \to \mathbb{R}$ appearing in~\eqref{eqn:multichordal-energy-definition}; 

\item \label{item_multi3}
and the goodness of the multichordal Loewner energy $\mcenergy{D}{\alpha}$ defined in~\eqref{eqn:multichordal-energy-definition}. 
\end{enumerate}
\Cref{item_multi1} is just the chordal case of \Cref{thm:radial-LDP}. 
\Cref{item_multi2} follows immediately, since by~\cite[Lemma~3.2]{Peltola-Wang:LDP}, 
$\loopterm{D}$ is continuous already when $\Hpaths[\alpha]$ is equipped with the Hausdorff metric,
and the topology we are interested in is finer. 
For \Cref{item_multi3}, it remains to note that the proof of \cite[Proposition~3.13]{Peltola-Wang:LDP} (and of \cite[Lemma~2.7]{Peltola-Wang:LDP})
shows the goodness of $\mcenergy{D}{\alpha}$ also with respect to the topology induced by $\dHpaths$, 
since images of paths under uniformly convergent sequences of maps converge in the metric $\dHpaths$.
This proves \Cref{thm:multichordal-LDP}.

Note that curves on $\overline{\Xpaths}_{<\infty}$ are bounded, so the topologies induced by $d_{\Xpaths[]}^E$ and $\dXpaths$ coincide. 
Since $d_{\Xpaths}^\circ \le d_{\Xpaths[]}^E$, it remains to prove that for each time $T \in [0,\infty)$, 
curve $\eta \in \Xpathscl[T]$ and radius $\varepsilon > 0$ there exists a radius  $\delta > 0$ such that 
\begin{align*}
\Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta} \cap \overline{\Xpaths}_{<\infty} \subset \Bmetric[d_{\Xpaths[]}^E]{\eta}{\varepsilon} . 
\end{align*}
Let $\delta > 0$, and take $\gamma \in \smash{\Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta} \cap \overline{\Xpaths}_{<\infty}}$ with parameterization $\gamma \colon [0,T_\gamma] \to \overline {\mathbf{D}}$, 
so that there exists a reparameterization $\sigma = \sigma_\gamma \colon [0,T_\gamma] \to [0,T]$ 
with $\normUniform{\eta-\gamma\circ\sigma} < \delta$. Write
\begin{align*}
u_\gamma \; := \; \sup_{s \in [0,T_\gamma]}|\sigma(s)-s| = \sup_{s \in [0,T]} |s - \sigma^{-1}(s)|
\; \geq \; |T_\gamma - \sigma(T_\gamma)|
\; = \; |T_\gamma - T|.
\end{align*}
Our aim is to bound the Euclidean distance $d_{\Xpaths[]}^E(\gamma, \eta)$ in terms of $\delta$ and $u_\gamma$, 
and then show that as $\delta \to 0$, we have $u_\gamma \to 0$ uniformly in $\gamma \in \smash{\Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta} \cap \overline{\Xpaths}_{<\infty}}$. 
Setting $\tilde{T} = T \wedge T_\gamma$, $\tilde{\gamma} = \gamma|_{[0,\tilde{T}]}$, and $\tilde\eta = \eta|_{[0, \tilde{T}]}$, we have
\begin{align}\label{eq:bound_dXpathsEucl}
d_{\Xpaths[]}^E(\gamma, \eta)
 \; \le \;  \textnormal{osc}(\gamma, u_\gamma)  \; + \;  \normUniform{\tilde\eta - \tilde{\gamma}}  \; + \;  \textnormal{osc}(\eta, u_\gamma),
\end{align}
where $\textnormal{osc}(\eta, u) := \underset{|t-s| \le u}{\sup} \, |\eta(s)-\eta(t)|$, for $u > 0$.

\begin{itemize}[leftmargin=*]
\item 
Let us first bound $\textnormal{osc}(\gamma, u_\gamma)$. 
For each $s, t \in [0,T_\gamma]$ with $|t-s| < u_\gamma$, we have
\begin{align*}
|\gamma(t)-\gamma(s)| \; \le \;
\underbrace{|\gamma(t)-\eta(\sigma^{-1}(t))|}_{< \, \delta} 
\; + \; |\eta(\sigma^{-1}(t)) - \eta(\sigma^{-1}(s))| 
\; + \; \underbrace{|\eta(\sigma^{-1}(s)) - \gamma(s)|}_{< \, \delta}.
\end{align*}
To bound the second term, note that
\begin{align*}
|\sigma^{-1}(t)-\sigma^{-1}(s)|  \; \le \;  |\sigma^{-1}(t)-t|  \; + \;  |t-s|  \; + \;  |s-\sigma^{-1}(s)|  \; \le \;  3u_\gamma ,
\end{align*}
so $|\eta(\sigma^{-1}(t)) - \eta(\sigma^{-1}(s))| \le \textnormal{osc}(\eta, 3u_\gamma)$. 
Plugging these bounds back to \Cref{eq:bound_dXpathsEucl} and taking 
the supremum over $s, t \in [0,T_\gamma]$ with $|t-s| \le u_\gamma$ then yields
\begin{align*}
\textnormal{osc}(\gamma, u_\gamma)  \; \le \;  2\delta  \; + \;  \textnormal{osc}(\eta, 3u_\gamma).
\end{align*}

\item 
Let us next bound $\normUniform{\tilde\eta - \tilde{\gamma}}$. For each $s, t \in [0,\tilde{T}]$, we have
\begin{align*}
|\gamma(\sigma(t)) - \gamma(\sigma(s))| 
\; \le \;\; & 
\underbrace{|\gamma(\sigma(t))-\eta(t)|}_{< \, \delta}  
\; + \; |\eta(t)-\eta(s)| 
\; + \; \underbrace{|\eta(s)-\gamma(\sigma(s))|}_{< \, \delta}  
\\
\; < \;\; & 2\delta \; + \; \textnormal{osc}(\eta, |s-t|) .
\end{align*}
Hence, for each $t \in [0,\tilde{T}]$, we have
\begin{align*}
|\eta(t)-\gamma(t)| 
\; \le \;\; & 
\underbrace{|\eta(t)-\gamma(\sigma(t))|}_{< \, \delta}  
\; + \; |\gamma(\sigma(t)) - \gamma(\sigma(\sigma^{-1}(t)))| 
\\
\; < \;\; & 3\delta + \textnormal{osc}(\eta, u_\gamma),
\end{align*}
which implies that $\normUniform{\tilde\eta-\tilde{\gamma}} \le 3\delta + \textnormal{osc}(\eta, u_\gamma)$. 
All in all, we thus have
\begin{align*}
d_{\Xpaths[]}^E(\gamma, \eta) \; \le \; 5\delta \; + \; 2\,\textnormal{osc}(\eta, u_\gamma) \; + \; \textnormal{osc}(\eta, 3u_\gamma) ,
\end{align*}
and it remains to show that 
$u_\gamma \to 0$ as $\delta \to 0$, uniformly in $\gamma \in \smash{\Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta} \cap \overline{\Xpaths}_{<\infty}}$. 
\end{itemize}

\begin{enumerate}[leftmargin=*, label=\textnormal{(\roman*)}]
\item {\bf Radial case.}
Assume the case $\Xpaths = \Dpaths$. For $\xi \in \Dpathscl$ and $t \ge 0$, write
\begin{align*}
D^\xi_t := (\mathbb{D}\smallsetminus\xi_{[0,t]})_0, \qquad g^\xi_t = g_{\xi[0,t]} \colon D^\xi_t \to \mathbb{D}, \qquad \textnormal{and} \qquad f^\xi_t = (g^\xi_t)^{-1} \colon \mathbb{D} \to D^\xi_t.
\end{align*}
Using Koebe estimates with $\xi = \gamma$ 
(see, e.g.,~\cite[Theorem~1.3~\&~Corollary~1.4]{Pommerenke:Boundary_behaviour_of_conformal_maps}), 
we see that 
\begin{align*}
\mathrm{dist}\,(f^\gamma_t(z), \partial D^\gamma_t) 
\; \ge & \;\; \frac{1}{4}(1-|z|^2) \, |(f^\gamma_t)'(z)| 
\; \ge \; \frac{|(f^\gamma_t)'(0)|}{4}\frac{(1-|z|^2)(1-|z|)}{(1+|z|^3)} 
\\
\; \ge & \;\; \frac{(1-|z|)^2}{8\,\mathrm{dist}\,(0, \partial D^\gamma(t))} , \qquad t \in [0, T_\gamma] , \; z \in \mathbb{D} .
\end{align*}
Since $\gamma \in \smash{\Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta} \cap \overline{\Xpaths}_{<\infty}}$, 
we can estimate $\mathrm{dist}\,(0,\partial D^\gamma_t) \le \mathrm{dist}\,(0, \eta[0,T]) + \delta$, so
\begin{align*}
\mathrm{dist}\,(f^\gamma_t(r\mathbb{D}), \gamma[0,t]) 
\; \ge \; \mathrm{dist}\,(f^\gamma_t(r\mathbb{D}), \partial D^\gamma_t) 
\; \ge \; \frac{(1-r)^2}{8\,(\mathrm{dist}\,(0,\eta) + \delta)} , \qquad r \in (0,1) .
\end{align*}
Taking $r = r(\delta) = 1 - 2\sqrt{2 \delta (\mathrm{dist}\,(0,\eta) + \delta)}$ (positive for small enough $\delta$), we obtain 
\begin{align*}
\mathrm{dist}\,(f^\gamma_t(r\mathbb{D}), \gamma[0,t]) \ge 2\delta.
\end{align*} 
To show the uniformity in $\gamma$, 
consider another $\tilde\gamma \in \Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta}$ parameterized by capacity, 
with reparameterization $\tilde \sigma \colon [0,T_{\tilde\gamma}] \to [0,T]$ so that $\normUniform{\tilde\gamma\circ\tilde\sigma - \eta} < \delta$. 
Then, we have $\normUniform{\tilde\gamma\circ\tilde\sigma - \gamma\circ\sigma} < 2\delta$, which implies that
\begin{align*}
\tilde\gamma[0,\sigma(t)] 
\; \subset \; \Bmetric{\gamma[0,\sigma(t)]}{2\delta} \cap \overline{\mathbb{D}} 
\; \subset \; \overline{\mathbb{D}}\smallsetminus f^\gamma_{\sigma(t)}(r\mathbb{D}) 
\; =: \; A^\gamma_{\sigma(t)}(r).
\end{align*}
Note that $A^\gamma_t(r) = \filling{\gamma[0,t]}\cup f^\gamma_t(A^\gamma_0(r))$, where $A^\gamma_0(r) = A(r) = \overline{\mathbb{D}}\smallsetminus r\mathbb{D}$. 
Thus, we have $g_{A^\gamma_t(r)}(\cdot) = (g_{A(r)} \circ g^\gamma_t)(\cdot) = r^{-1} g^\gamma_t(\cdot)$. 
By monotonicity, we thus obtain
\begin{align*}
e^{\tilde\sigma(t)} = (g^{\tilde\gamma}_{\tilde\sigma(t)})'(0) \le (g_{A^\gamma_{\sigma(t)}(r)})'(0) = r^{-1}e^{\sigma(t)}.
\end{align*}
Taking logarithms of both sides and rearranging yields $\tilde\sigma(t) - \sigma(t) \le - \log r$. 
By symmetry, we have $|\sigma(t)-\tilde\sigma(t)| \le -\log r$. 
Choosing $\tilde\gamma = \eta$ and $\tilde\sigma = \mathrm{\textnormal{id}}$ thus gives
\begin{align*}
\sup_{s \in [0,T]}|s - \sigma(s)| 
\; \le \; -\log r 
\quad \xrightarrow{\delta \to 0} \quad 0 , 
\qquad \textnormal{uniformly for } \gamma \in \Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta}.
\end{align*}

\item {\bf Chordal case.} 
Next, assume the case $\Xpaths = \Hpaths$. 
By~\cite[Proposition~6.5]{Berestrycki-Norris:Lecture_notes_on_SLE},  we have
\begin{align*}
\textnormal{hcap}(\Bmetric{\gamma[0,t]}{\delta}) 
\; \le \; t  \; + \;  \frac{16}{\pi}\mathrm{rad}(\Bmetric{\gamma[0,t]}{\delta})^{3/2}\delta^{1/2}, \qquad t \in [0,T_\gamma] ,
\end{align*}
where $\mathrm{rad}(K) := \inf\{R > 0 \colon K \subset \Bmetric{x}{R} \textnormal{ for some } x \in \mathbb{R}\}$. 
As $\gamma \in \smash{\Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta} \cap \overline{\Xpaths}_{<\infty}}$,
we can estimate 
\begin{align*}
\mathrm{rad}(\Bmetric{\gamma[0,t]}{\delta}) 
\; \le \; \mathrm{rad}(\Bmetric{\gamma[0,T]}{\delta}) 
\; \le \; \mathrm{rad}(\eta[0,T]) +  2\delta,
\end{align*}
from which we obtain the uniform bound
\begin{align*}
\textnormal{hcap}\big(\Bmetric{\gamma[0,t]}{\delta}\big) 
\; \le \; t  \; + \;  \underbrace{\frac{16}{\pi}\big(\mathrm{rad}(\eta[0,T] + 2\delta)\big)^{3/2}\delta^{1/2}}_{=: \, r(\delta)} 
, \qquad \gamma \in \Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta} .
\end{align*}
Finally, using monotonicity of the capacity, we deduce that 
\begin{align*}
2\sigma(t) \; =  \;\; & \textnormal{hcap}(\gamma[0,\sigma(t)])) 
\; \le \; \textnormal{hcap}\big(\Bmetric{\eta[0,T]}{\delta}\big) 
\; \le \; t + r(\delta),
\\
2 t = \;\; & \textnormal{hcap}\big(\eta[0,T]\big) 
\; \le \; \textnormal{hcap}\big(\Bmetric{\gamma[0,\sigma(t)]}{\delta}\big) 
\; \le \; \sigma(t) + r(\delta) .
\end{align*}
This implies that $|\sigma(t)-t| \le r(\delta) \to 0$ as $\delta \to 0$, 
uniformly for $\gamma \in \smash{\Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta}}$.
\qedhere
