\; \le \; t  \; + \;  \underbrace{\frac{16}{\pi}\big(\mathrm{rad}(\eta[0,T] + 2\delta)\big)^{3/2}\delta^{1/2}}_{=: \, r(\delta)} 
, \qquad \gamma \in \Bmetric[d_{\Xpaths}^\circ]{\eta}{\delta} .
\end{align*}

\begin{align}\label{eqn:concatenation}
(\gamma*\eta)(t) 
\; := \; 
\begin{cases}
\gamma(t), & t \in [0,T] , \\
\hat f_T \big( \eta(t-T) \big), & t > T .
\end{cases}
\end{align}

\begin{align}\label{eqn:paths-concat-ineq}
	d_{\Xpaths}^\circ \big(\gamma^n * \eta^n, \gamma * \eta \big) 
	\; \le \; \max\Big(\underbrace{d_{\Xpaths}^\circ \big(\gamma^n, \gamma \big)}_{\underset{n \to \infty}{\longrightarrow} \; 0} ,\; d_{\Xpaths}^\circ \big(\hat f^n_{T^n}(\eta^n), \hat f_T(\eta) \big)\Big) ,
\end{align}

\begin{align} \label{eq:composed_maps}
\begin{split}
	\tilde f := \; & \varphi_{a_0} \circ \hat f_T \circ \varphi_z^{-1} \;\, \colon \, \mathbb{D} \to \mathbb{D} \smallsetminus \varphi_{a_0}(\gamma(0,T]) ,
	 \\
	 \tilde f^n := \; & \varphi_{a_0} \circ \hat f^n_{T_n} \circ \varphi_{z_n}^{-1} \colon \mathbb{D} \to \mathbb{D} \smallsetminus \varphi_{a_0}(\gamma^n(0,T^n]).
\end{split}
\end{align}

\label{thm:contraction-principle-generalized}
Let $X$ and $Y$ be Hausdorff topological spaces and $f \colon X \to Y$ a measurable map. 
Suppose that the family $(P^\varepsilon)_{\varepsilon>0}$ of probability measures on $X$ satisfies an LDP 
with rate function $I \colon X \to [0,+\infty]$.
Consider the pushforward probability measures $Q^\varepsilon := P^\varepsilon\circ f^{-1}$ of $P^\varepsilon$ by $f$. 
Define $J \colon Y \to [0,+\infty]$ by
\begin{align*}
J(y) := I(f^{-1}\{y\}) 
:= \inf_{x \in f^{-1}\{y\}} I(x) , \qquad y \in Y .
\end{align*}

\begin{enumerate}[leftmargin=*, label=\textnormal{(\roman*)}]
\item \label{item:LDP_gen}
Suppose that for each $M \in [0,\infty)$, there exists a closed set $E = E(M) \subset X$ only depending on $M$ 
such that $f$ restricted to $E$ is continuous and
\begin{align} \label{eq:exp_tighness_gen}
\varlimsup_{\varepsilon\to 0} \varepsilon\log P^\varepsilon[X \smallsetminus E] \le -M.
\end{align}
Then, the measures $(Q^\varepsilon)_{\varepsilon > 0}$ satisfy the LDP bounds: 
we have
\begin{align*}
\varliminf_{\kappa \to 0+}\varepsilon\log Q^\varepsilon[G] \ge 
-J(G) 
\qquad \textnormal{and} \qquad
\varlimsup_{\kappa \to 0+}\varepsilon\log Q^\varepsilon[F] \le 
-J(F),
\end{align*}
for every open $G \subset Y$ and closed $F \subset Y$.

\item \label{item:good}
If furthermore $I$ is a good rate function and $f$ is continuous on $I^{-1}[0,\infty)$, 
then also $J$ is a good rate function.
\end{enumerate}

\begin{align*}
J(y) := I(f^{-1}\{y\}) 
:= \inf_{x \in f^{-1}\{y\}} I(x) , \qquad y \in Y .
\end{align*}

\begin{align} \label{eq:exp_tighness_gen}
\varlimsup_{\varepsilon\to 0} \varepsilon\log P^\varepsilon[X \smallsetminus E] \le -M.
\end{align}

First, take a closed set $F \subset Y$. 
For each $M > 0$, the set $E(M) \cap f^{-1}F$ is a closed subset of $X$, 
so by the union bound and the LDP for $(P^\varepsilon)_{\varepsilon>0}$, we obtain
\begin{align*}
\varlimsup_{\varepsilon \to 0}\varepsilon\log Q^\varepsilon[F] 
\;\le\;\;& \varlimsup_{\varepsilon \to 0}\varepsilon\log \Big(P^\varepsilon[E(M) \cap f^{-1}F] + P^\varepsilon[X \smallsetminus E(M)]\Big)\\
\;\le\;\;& - \min \big\{I(E(M) \cap f^{-1}F) , M \big\}
\;\le\; - \min \big\{I(f^{-1}F) , M \big\} \\
\xrightarrow{M \to \infty} \quad \;& -I(f^{-1}F) = -J(F).
\end{align*}
Next, take an open set $G \subset Y$. If $J(G) = \infty$, we trivially have
\begin{align*}
\varliminf_{\varepsilon \to 0}\varepsilon\log Q^\varepsilon[G] \ge -\infty = -J(G).
\end{align*}
Hence, we may fix $M > 0$ such that $J(G) < M < \infty$ and write $E = E(M)$.
As $f|_E$ is continuous, we can find an open set $G' \subset X$ such that $G' \cap E = f^{-1}G \cap E$. 
Now, we have
\begin{align}\label{eqn:QG}
Q^\varepsilon(G) \;=\;  P^\varepsilon[f^{-1}G] \; \ge\;  P^\varepsilon[G' \cap E] \; \ge\;  P^\varepsilon[G'] - P^\varepsilon[X \smallsetminus E].
\end{align}
We will soon check that $I(G') \le J(G)$. Assuming this, the LDP for $P^\varepsilon$ gives
\begin{align*}
\varliminf_{\varepsilon \to 0}\varepsilon\log P^\varepsilon[G'] 
\;\ge\; -J(G) 
\;>\; -M 
\;\ge\; \varlimsup_{\varepsilon \to 0}\varepsilon\log P^\varepsilon[X \smallsetminus E],
\end{align*}
which together with~\eqref{eqn:QG} and the LDP for $(P^\varepsilon)_{\varepsilon > 0}$ gives
\begin{align*}
\varliminf_{\varepsilon \to 0}\varepsilon\log Q^\varepsilon[G] 
\;\ge\; \varliminf_{\varepsilon \to 0}\varepsilon\log(P^\varepsilon[G'] - P^\varepsilon[X \smallsetminus E]) 
\;=\; \varliminf_{\varepsilon \to 0}\varepsilon\log P^\varepsilon[G'] 
\;\ge\; -J(G).
\end{align*}
It remains to check that $I(G') \le J(G)$. To this end, note that 
\begin{align*}
J(G) = \min \Big\{ I(f^{-1}G \cap E) , \; \underbrace{I(f^{-1}G \cap (X \smallsetminus E))}_{\;\ge\; I(X \smallsetminus E)} \Big\},
\end{align*} 
and using the LDP for $(P^\varepsilon)_{\varepsilon > 0}$ and the assumption~\eqref{eq:exp_tighness_gen},
we see that $I(X \smallsetminus E) \ge M > J(G)$, 
which implies $I(f^{-1}G \cap E) = J(G)$. Hence, we conclude that
\begin{align*}
I(G') \;\le\; I(G' \cap E) \;=\; I(f^{-1}G \cap E) \;=\; J(G).
\end{align*}
This proves \Cref{item:LDP_gen}. \Cref{item:good} follows from the fact that 
$J^{-1}[0,M] = f(I^{-1}[0,M])$ is compact as an image of a compact set $I^{-1}[0,M]$ under a continuous map $f|_{I^{-1}[0,\infty)}$.

\begin{align*}
\varlimsup_{\varepsilon \to 0}\varepsilon\log Q^\varepsilon[F] 
\;\le\;\;& \varlimsup_{\varepsilon \to 0}\varepsilon\log \Big(P^\varepsilon[E(M) \cap f^{-1}F] + P^\varepsilon[X \smallsetminus E(M)]\Big)\\
\;\le\;\;& - \min \big\{I(E(M) \cap f^{-1}F) , M \big\}
\;\le\; - \min \big\{I(f^{-1}F) , M \big\} \\
\xrightarrow{M \to \infty} \quad \;& -I(f^{-1}F) = -J(F).
\end{align*}

\begin{align*}
\varliminf_{\varepsilon \to 0}\varepsilon\log Q^\varepsilon[G] \ge -\infty = -J(G).
\end{align*}

\begin{align}\label{eqn:QG}
Q^\varepsilon(G) \;=\;  P^\varepsilon[f^{-1}G] \; \ge\;  P^\varepsilon[G' \cap E] \; \ge\;  P^\varepsilon[G'] - P^\varepsilon[X \smallsetminus E].
\end{align}

\begin{align*}
\varliminf_{\varepsilon \to 0}\varepsilon\log P^\varepsilon[G'] 
\;\ge\; -J(G) 
\;>\; -M 
\;\ge\; \varlimsup_{\varepsilon \to 0}\varepsilon\log P^\varepsilon[X \smallsetminus E],
\end{align*}

\begin{align*}
\varliminf_{\varepsilon \to 0}\varepsilon\log Q^\varepsilon[G] 
\;\ge\; \varliminf_{\varepsilon \to 0}\varepsilon\log(P^\varepsilon[G'] - P^\varepsilon[X \smallsetminus E]) 
\;=\; \varliminf_{\varepsilon \to 0}\varepsilon\log P^\varepsilon[G'] 
\;\ge\; -J(G).
\end{align*}

\begin{align*}
J(G) = \min \Big\{ I(f^{-1}G \cap E) , \; \underbrace{I(f^{-1}G \cap (X \smallsetminus E))}_{\;\ge\; I(X \smallsetminus E)} \Big\},
\end{align*}

\begin{align*}
I(G') \;\le\; I(G' \cap E) \;=\; I(f^{-1}G \cap E) \;=\; J(G).
\end{align*}
